def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The 3x3 solid squares cast full horizontal and vertical rays through their centers.
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[i][j] == color for i in range(r, r + 3) for j in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))
    for r, c, color in blocks:
        for j in range(w): out[r][j] = color
        for i in range(h): out[i][c] = color
    for i in range(h):
        for j in range(w):
            if sum(i == r for r, c, color in blocks) + sum(j == c for r, c, color in blocks) > 1:
                out[i][j] = 0
    return out
